const readline = require('node:readline');
const send = (message) => process.stdout.write(`${JSON.stringify({ jsonrpc: '2.0', ...message })}\n`);
const MERGE = {
  name: 'merge_pull_request',
  description: 'Merge a pull request of this repository',
  inputSchema: { type: 'object', properties: { number: { type: 'integer' } }, required: ['number'] },
  annotations: { destructiveHint: true },
};
readline.createInterface({ input: process.stdin }).on('line', (line) => {
  if (line.trim() === '') return;
  const message = JSON.parse(line);
  if (message.id === undefined) return;
  if (message.method === 'initialize') send({ id: message.id, result: { protocolVersion: message.params.protocolVersion, capabilities: { tools: {} }, serverInfo: { name: 'forge', version: '1.0.0' } } });
  else if (message.method === 'tools/list') send({ id: message.id, result: { tools: [MERGE] } });
  else if (message.method === 'tools/call') send({ id: message.id, result: { content: [{ type: 'text', text: `merged pull request ${message.params.arguments.number}` }] } });
  else send({ id: message.id, error: { code: -32601, message: `method ${message.method} not found` } });
});
